const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const year = 2003;
  const startDate = ee.Date.fromYMD(year, 1, 1);
  const endDate = ee.Date.fromYMD(year, 12, 31);

  // Define points for each location
  const qldPoint = ee.Geometry.Point(141.0, -25.0); // Queensland, Australia (approx. central hot region)
  const lutDesertPoint = ee.Geometry.Point(59.0, 30.0); // Lut Desert, Iran (known hot spot)
  const elAziziaPoint = ee.Geometry.Point(13.0, 32.5); // El Azizia, Libya (known hot spot)

  // Use a small buffer for reducing region to capture local max rather than just a single pixel
  const buffer_m = 1000;
  const qldGeom = qldPoint.buffer(buffer_m);
  const lutDesertGeom = lutDesertPoint.buffer(buffer_m);
  const elAziziaGeom = elAziziaPoint.buffer(buffer_m);

  // 2. Data Acquisition & Check
  const collection = ee.ImageCollection('MODIS/051/MOD11A2')
    .filterDate(startDate, endDate)
    .select(['LST_Day_1km', 'QC_Day']); // Select LST band and Quality Control band

  // Function to mask clouds and scale LST
  const maskAndScaleLST = (image) => {
    const lstDay = image.select('LST_Day_1km');
    const qcDay = image.select('QC_Day');

    // MOD11A2 QC bits for cloud: Bit 6-7 (00 = not cloud contaminated)
    // Shift right by 6 and AND with 3 (binary 11) to get the 2-bit cloud flag
    const cloudFlag = qcDay.rightShift(6).bitwiseAnd(3);
    const goodQuality = cloudFlag.eq(0); // 00 means good quality (not cloud contaminated)

    // LST value is scaled by 0.02 and is in Kelvin. Convert to Celsius.
    const lstCelsius = lstDay.multiply(0.02).subtract(273.15);

    return lstCelsius.updateMask(goodQuality).copyProperties(image, ['system:time_start']);
  };

  const processedCollection = collection.map(maskAndScaleLST);

  // Check if collections are empty for each location
  const getCollectionSize = (geom, name) => {
    const size = collection.filterBounds(geom).size().getInfo();
    console.log(`${name} raw images: ${size}`);
    return size;
  };

  const qldSize = getCollectionSize(qldGeom, 'Queensland');
  const lutSize = getCollectionSize(lutDesertGeom, 'Lut Desert');
  const elAziziaSize = getCollectionSize(elAziziaGeom, 'El Azizia');

  if (qldSize === 0 || lutSize === 0 || elAziziaSize === 0) {
    console.log("C1: Empty Collection - No images found for one or more locations in 2003.");
    return;
  }

  // 3. Calculate Maximum LST for each location
  const getMaximumLST = (geom, name) => {
    const filteredCollection = processedCollection.filterBounds(geom);

    const count = filteredCollection.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geom,
      scale: 1000,
      maxPixels: 1e9
    }).get('LST_Day_1km');

    if (count === null || count.getInfo() === 0) {
      console.log(`C2: No Valid Pixels - After cloud masking, 0 valid pixels remain for ${name}.`);
      return null;
    }

    const maxLST = filteredCollection.max().reduceRegion({
      reducer: ee.Reducer.max(),
      geometry: geom,
      scale: 1000, // MODIS resolution is 1km, so use 1km scale
      maxPixels: 1e9
    }).get('LST_Day_1km');

    console.log(`${name} valid pixels: ${count.getInfo()}`);
    return maxLST.getInfo();
  };

  const maxLST_qld = getMaximumLST(qldGeom, 'Queensland');
  const maxLST_lutDesert = getMaximumLST(lutDesertGeom, 'Lut Desert');
  const maxLST_elAzizia = getMaximumLST(elAziziaGeom, 'El Azizia');

  // 4. Validation & Final Answer
  if (maxLST_qld === null || maxLST_lutDesert === null || maxLST_elAzizia === null) {
    console.log("C3: Calculation Failure - One or more max LST values could not be calculated.");
    return;
  }

  console.log(`Queensland Max LST (C): ${maxLST_qld.toFixed(2)}`);
  console.log(`Lut Desert Max LST (C): ${maxLST_lutDesert.toFixed(2)}`);
  console.log(`El Azizia Max LST (C): ${maxLST_elAzizia.toFixed(2)}`);

  const isQldHigher = maxLST_qld > maxLST_lutDesert && maxLST_qld > maxLST_elAzizia;

  if (isQldHigher) {
    console.log("A"); // Yes
  } else {
    console.log("B"); // No
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
